const key = ((($input.first() || {}).json || {}).key || '').toString().trim();
let taskId = null;
try { taskId = $('When Called').first().json.clickup_task_id || null; } catch (e) {}
let images = [];
try {
  const raw = $('When Called').first().json.input_images_json;
  const parsed = typeof raw === 'string' ? JSON.parse(raw || '[]') : (raw || []);
  if (Array.isArray(parsed)) {
    images = parsed
      .filter(b => b && (b.ref || b.url) && (b.type ? b.type === 'image' : true))
      .map((b, i) => ({
        ref: b.ref || b.url,
        mime: b.mime || 'image/jpeg',
        source_ref: (b.source_ref != null ? b.source_ref : (b.att_id != null ? b.att_id : ('img_' + i))),
        alt: b.alt || b.title || null,
        order: (b.order != null ? b.order : i),
        key: key,
        clickup_task_id: taskId
      }));
  }
} catch (e) { images = []; }
const do_upload = !!key && images.length > 0;
return [{ json: { key, clickup_task_id: taskId, images, do_upload, key_missing: !key, no_images: images.length === 0 } }];

const item = $input.item;
const meta = $('Split Out Images').item.json;
if (item.binary && item.binary.data) {
  const b = item.binary.data;
  b.mimeType = b.mimeType || meta.mime || 'image/jpeg';
  if (!b.fileName) {
    const ext = String(b.mimeType.split('/')[1] || 'jpg').replace('jpeg', 'jpg').split('+')[0];
    const safe = String(meta.source_ref != null ? meta.source_ref : (meta.order != null ? meta.order : 'img')).replace(/[^a-zA-Z0-9._-]/g, '_');
    b.fileName = 'input_' + safe + '.' + ext;
  }
}
return item;

const meta = $('Split Out Images').item.json;
const up = $json || {};
return { json: {
  ok: true,
  file_id: up.id || null,
  url: meta.ref,
  source_ref: meta.source_ref,
  mime: up.mime_type || meta.mime || 'image/jpeg',
  alt: meta.alt || null,
  order: meta.order
} };

const meta = $('Split Out Images').item.json;
const e = $json || {};
const err = (e.error && (e.error.message || e.error)) || e.message || 'fetch_failed';
return { json: { ok: false, source_ref: meta.source_ref, warn_source: 'files-api/fetch-failed', err: String(err).slice(0, 300), alt: meta.alt || null } };

const meta = $('Split Out Images').item.json;
const e = $json || {};
const err = (e.error && (e.error.message || e.error)) || e.message || 'upload_failed';
return { json: { ok: false, source_ref: meta.source_ref, warn_source: 'files-api/upload-failed', err: String(err).slice(0, 300), alt: meta.alt || null } };

const rows = $input.all().map(i => i.json).filter(j => j && (j.ok === true || j.ok === false || j.do_upload === false));
const oks = rows.filter(j => j.ok === true && j.file_id);
const okNoId = rows.filter(j => j.ok === true && !j.file_id);
const drops = rows.filter(j => j.ok === false);
const sentinel = rows.find(j => j.do_upload === false);
const file_map = oks.map(j => ({ file_id: j.file_id, url: j.url, source_ref: j.source_ref, mime: j.mime, alt: j.alt, order: j.order }));
const warnings = [];
for (const d of drops) warnings.push({ source: d.warn_source || 'files-api/upload-failed', source_ref: d.source_ref, err: d.err || 'unknown', severity: 'WARN' });
for (const d of okNoId) warnings.push({ source: 'files-api/upload-no-id', source_ref: d.source_ref, err: 'upload succeeded but no file_id returned', severity: 'WARN' });
if (sentinel && sentinel.key_missing) warnings.push({ source: 'files-api/key-unreachable', err: 'anthropic key not reachable from Vault; proceeding text-only', severity: 'WARN' });
let taskId = null;
try { taskId = $('When Called').first().json.clickup_task_id || null; } catch (e) {}
if (!taskId) { const f = rows.find(j => j.clickup_task_id); taskId = f ? f.clickup_task_id : null; }
return [{ json: { file_map, warnings, clickup_task_id: taskId, uploaded_count: file_map.length, dropped_count: drops.length + okNoId.length } }];

