insert into public.agent_input_file_map (file_id, url, mime, source_ref)
select file_id, url, mime, source_ref
from jsonb_to_recordset($1::jsonb) as x(file_id text, url text, mime text, source_ref text)
where file_id is not null
on conflict (file_id) do update set url = excluded.url, mime = excluded.mime, source_ref = excluded.source_ref;

