const out = $('Aggregate').first().json || {};
const up = $input.first();
const failed = !!(up && up.json && up.json.error);
const warnings = Array.isArray(out.warnings) ? out.warnings.slice() : [];
if (failed) warnings.push({ source: 'agent-input-file-map/write-failed', err: 'failed to persist file_id->url map; image MCP reference resolution may fail for these images', severity: 'WARN' });
return [{ json: Object.assign({}, out, { warnings: warnings }) }];
